/** v2閉wire候補。構造一致を真正資格や保存成功へ読替えない。 */
export type CanonicalUnsigned = string;
export type CanonicalPositive = string;
export type Score = Readonly<{readonly "home": CanonicalUnsigned; readonly "away": CanonicalUnsigned}>;
export type StateFields = Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": CanonicalUnsigned; readonly "state.count.balls": CanonicalUnsigned; readonly "state.outs": CanonicalUnsigned; readonly "state.runners": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "state.battingOrder": CanonicalUnsigned; readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": boolean; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>;
export type Scoreboard = Readonly<{readonly "inningScores": Score; readonly "hits": CanonicalUnsigned; readonly "errors": CanonicalUnsigned; readonly "strikeouts": CanonicalUnsigned; readonly "walks": CanonicalUnsigned}>;
export type Snapshot = Readonly<{readonly "stateFields": StateFields; readonly "scoreboard": Scoreboard}>;
export type StatFlags = Readonly<{readonly "投球回算入アウト": boolean; readonly "投球数": boolean; readonly "奪三振": boolean; readonly "与四球": boolean; readonly "与死球": boolean; readonly "被安打": boolean; readonly "被本塁打": boolean; readonly "失点": boolean; readonly "失策": boolean; readonly "打席": boolean; readonly "打数": boolean; readonly "安打": boolean; readonly "本塁打": boolean; readonly "塁打": boolean; readonly "犠打": boolean; readonly "犠飛": boolean; readonly "四球": boolean; readonly "死球": boolean; readonly "三振": boolean; readonly "打撃妨害出塁": boolean; readonly "走塁妨害出塁": boolean; readonly "得点": boolean; readonly "打点": boolean}>;
export type StateDifference = Readonly<{readonly "state.half"?: Readonly<{readonly "before": ("top" | "bottom"); readonly "after": ("top" | "bottom")}>; readonly "state.count.strikes"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.count.balls"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.outs"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.runners"?: Readonly<{readonly "before": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third"); readonly "after": ("empty" | "first" | "second" | "third" | "first-second" | "first-third" | "second-third" | "first-second-third")}>; readonly "state.battingOrder"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "state.tiebreakActive"?: Readonly<{readonly "before": boolean; readonly "after": boolean}>; readonly "state.gameEnded"?: Readonly<{readonly "before": boolean; readonly "after": boolean}>; readonly "state.inning"?: Readonly<{readonly "before": CanonicalPositive; readonly "after": CanonicalPositive}>; readonly "state.score"?: Readonly<{readonly "before": Score; readonly "after": Score}>}>;
export type ScoreboardDifference = Readonly<{readonly "inningScores"?: Readonly<{readonly "before": Score; readonly "after": Score}>; readonly "hits"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "errors"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "strikeouts"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>; readonly "walks"?: Readonly<{readonly "before": CanonicalUnsigned; readonly "after": CanonicalUnsigned}>}>;
export type HistoryEntry = Readonly<{readonly "kind": "confirmed-play"; readonly "difference": Readonly<{readonly "stateFields": StateDifference; readonly "scoreboard": ScoreboardDifference; readonly "statFlags": StatFlags}>}>;
export type Request = Readonly<{readonly "eventKind": "batting-result"; readonly "resultId": string; readonly "pitchEventKind": string; readonly "before": Snapshot; readonly "history": Readonly<{readonly "stack": readonly (HistoryEntry)[]}>}>;
export type WalkRequest = Readonly<{readonly "eventKind": "batting-result"; readonly "resultId": "batting-result.walk"; readonly "pitchEventKind": "pitch-event"; readonly "before": Readonly<{readonly "stateFields": Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": ("0" | "1" | "2"); readonly "state.count.balls": ("3"); readonly "state.outs": ("0" | "1" | "2"); readonly "state.runners": "empty"; readonly "state.battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": false; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>; readonly "scoreboard": Scoreboard}>; readonly "history": Readonly<{readonly "stack": readonly (HistoryEntry)[]}>}>;
export type HitByPitchRequest = Readonly<{readonly "eventKind": "batting-result"; readonly "resultId": "batting-result.hit-by-pitch"; readonly "pitchEventKind": "pitch-event"; readonly "before": Readonly<{readonly "stateFields": Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": ("0" | "1" | "2"); readonly "state.count.balls": ("0" | "1" | "2" | "3"); readonly "state.outs": ("0" | "1" | "2"); readonly "state.runners": "empty"; readonly "state.battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": false; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>; readonly "scoreboard": Scoreboard}>; readonly "history": Readonly<{readonly "stack": readonly (HistoryEntry)[]}>}>;
export type TerminalPitchRequest = (WalkRequest | HitByPitchRequest);
export type AfterSnapshot = Readonly<{readonly "stateFields": Readonly<{readonly "state.half": ("top" | "bottom"); readonly "state.count.strikes": "0"; readonly "state.count.balls": "0"; readonly "state.outs": ("0" | "1" | "2"); readonly "state.runners": "first"; readonly "state.battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9"); readonly "state.tiebreakActive": boolean; readonly "state.gameEnded": false; readonly "state.inning": CanonicalPositive; readonly "state.score": Score}>; readonly "scoreboard": Scoreboard}>;
export type WalkValue = Readonly<{readonly "countEffect": {"strikes":{"kind":"reset"},"balls":{"kind":"reset"}}; readonly "plateAppearanceEnded": true; readonly "batterDestination": {"kind":"reach","base":"1"}; readonly "runnerDefaultAdvance": {"first":{"modality":"not-applicable","destination":null},"second":{"modality":"not-applicable","destination":null},"third":{"modality":"not-applicable","destination":null}}; readonly "outEffect": {"count":"0","targets":[]}; readonly "statFlags": {"投球回算入アウト":false,"投球数":true,"奪三振":false,"与四球":true,"与死球":false,"被安打":false,"被本塁打":false,"失点":false,"失策":false,"打席":true,"打数":false,"安打":false,"本塁打":false,"塁打":false,"犠打":false,"犠飛":false,"四球":true,"死球":false,"三振":false,"打撃妨害出塁":false,"走塁妨害出塁":false,"得点":false,"打点":false}; readonly "after": AfterSnapshot; readonly "historyContext": readonly (HistoryEntry)[]}>;
export type HitByPitchValue = Readonly<{readonly "countEffect": {"strikes":{"kind":"reset"},"balls":{"kind":"reset"}}; readonly "plateAppearanceEnded": true; readonly "batterDestination": {"kind":"reach","base":"1"}; readonly "runnerDefaultAdvance": {"first":{"modality":"not-applicable","destination":null},"second":{"modality":"not-applicable","destination":null},"third":{"modality":"not-applicable","destination":null}}; readonly "outEffect": {"count":"0","targets":[]}; readonly "statFlags": {"投球回算入アウト":false,"投球数":true,"奪三振":false,"与四球":false,"与死球":true,"被安打":false,"被本塁打":false,"失点":false,"失策":false,"打席":true,"打数":false,"安打":false,"本塁打":false,"塁打":false,"犠打":false,"犠飛":false,"四球":false,"死球":true,"三振":false,"打撃妨害出塁":false,"走塁妨害出塁":false,"得点":false,"打点":false}; readonly "after": AfterSnapshot; readonly "historyContext": readonly (HistoryEntry)[]}>;
export type SuccessResponse = Readonly<{readonly "ok": true; readonly "value": (WalkValue | HitByPitchValue)}>;
export type FailureResponse = Readonly<{readonly "ok": false; readonly "error": Readonly<{readonly "code": ("INVALID_JSON" | "INVALID_REQUEST" | "INVALID_DECIMAL_INTEGER" | "UNSUPPORTED_T1_SCOPE")}>}>;
export type TerminalPitchResponse = (SuccessResponse | FailureResponse);
export type SavedRuleWire = Readonly<{readonly "regulationInnings": string; readonly "coldConditions": readonly (Readonly<{readonly "pointDifference": string; readonly "startInning": string}>)[]; readonly "extensionLimit": (null | string); readonly "tiebreak": (null | Readonly<{readonly "startInning": string; readonly "runnerPlacement": string; readonly "leadoffRule": string}>); readonly "dh": boolean}>;
export type OrdinaryT2 = Readonly<{readonly "kind": "evaluated-no-end-condition"; readonly "scope": "ordinary37"; readonly "evaluation_point": "post-play"; readonly "basis": Readonly<{readonly "regulationInnings": string; readonly "inning": string; readonly "half": ("top" | "bottom"); readonly "halfCompleted": false; readonly "coldBranches": readonly (("COLD-01" | "COLD-04" | "COLD-06"))[]; readonly "coldAggregate": "COLD-07"; readonly "drawBranch": ("DRAW-07" | "DRAW-08"); readonly "scoreUnchanged": true; readonly "outsUnchanged": true; readonly "priorOpen": true; readonly "tiebreakActive": boolean; readonly "configuredExtensionLimit": (null | string)}>}>;
export type T2NoEndCore = (Readonly<{readonly "kind": "evaluated-no-end-condition"; readonly "evaluation_point": "post-play"; readonly "basis": Readonly<{readonly "regulation": Readonly<{readonly "kind": "before-regulation-completion"; readonly "regulation_innings": "7"; readonly "observed_inning": "1"; readonly "observed_half": "top"}>; readonly "cold": Readonly<{readonly "kind": "no-configured-cold-condition"}>; readonly "extra_and_draw": Readonly<{readonly "kind": "before-extra-inning-boundary"; readonly "configured_extension_limit": null}>; readonly "walk_off": Readonly<{readonly "kind": "top-half-without-score-change"}>}>}> | Readonly<{readonly "kind": "evaluated-no-end-condition"; readonly "evaluation_point": "post-play"; readonly "basis": Readonly<{readonly "regulation": Readonly<{readonly "kind": "before-regulation-completion"; readonly "regulation_innings": "9"; readonly "observed_inning": "1"; readonly "observed_half": "top"}>; readonly "cold": Readonly<{readonly "kind": "no-configured-cold-condition"}>; readonly "extra_and_draw": Readonly<{readonly "kind": "before-extra-inning-boundary"; readonly "configured_extension_limit": null}>; readonly "walk_off": Readonly<{readonly "kind": "top-half-without-score-change"}>}>}> | Readonly<{readonly "kind": "evaluated-no-end-condition"; readonly "evaluation_point": "post-play"; readonly "basis": Readonly<{readonly "regulation": Readonly<{readonly "kind": "before-regulation-completion"; readonly "regulation_innings": "9"; readonly "observed_inning": "1"; readonly "observed_half": "top"}>; readonly "cold": Readonly<{readonly "kind": "no-configured-cold-condition"}>; readonly "extra_and_draw": Readonly<{readonly "kind": "before-extra-inning-boundary"; readonly "configured_extension_limit": "9"}>; readonly "walk_off": Readonly<{readonly "kind": "top-half-without-score-change"}>}>}>);
export type OrdinaryT2Basis = Readonly<{readonly "regulationInnings": string; readonly "inning": string; readonly "half": ("top" | "bottom"); readonly "halfCompleted": false; readonly "coldBranches": readonly (("COLD-01" | "COLD-04" | "COLD-06"))[]; readonly "coldAggregate": "COLD-07"; readonly "drawBranch": ("DRAW-07" | "DRAW-08"); readonly "scoreUnchanged": true; readonly "outsUnchanged": true; readonly "priorOpen": true; readonly "tiebreakActive": boolean; readonly "configuredExtensionLimit": (null | string)}>;
export type Uuid = string;
export type Digest = string;
export type Unsigned = string;
export type Positive = string;
export type V1Ref = Readonly<{readonly "version": "1"; readonly "tenantId": Uuid; readonly "gameId": Uuid; readonly "generation": string; readonly "length": Unsigned}>;
export type Checkpoint = Readonly<{readonly "id": Uuid; readonly "revision": Positive; readonly "digest": Digest}>;
export type PrefixRef = Readonly<{readonly "version": "2"; readonly "scope": "play-prefix-v2"; readonly "tenantId": Uuid; readonly "gameId": Uuid; readonly "generation": string; readonly "length": Unsigned; readonly "checkpoint": Checkpoint; readonly "historyVersion": Unsigned; readonly "origin": V1Ref}>;
export type PlayIdentity = Readonly<{readonly "eventId": Uuid; readonly "d5": Uuid; readonly "playId": Uuid}>;
export type Position = Readonly<{readonly "d1": Unsigned; readonly "d2": Unsigned; readonly "appliedWatermark": Unsigned}>;
export type Participant = Readonly<{readonly "batterId": Uuid; readonly "pitcherId": Uuid; readonly "battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")}>;
export type NextBatter = Readonly<{readonly "batterId": Uuid; readonly "battingOrder": ("1" | "2" | "3" | "4" | "5" | "6" | "7" | "8" | "9")}>;
export type Runner = Readonly<{readonly "runnerId": Uuid; readonly "responsiblePitcherId": Uuid; readonly "base": ("1" | "2" | "3"); readonly "status": "継続"; readonly "statusSource": "auto"}>;
export type PlayT2 = Readonly<{readonly "kind": "evaluated-no-end-condition"; readonly "scope": "play-prefix-v2"; readonly "evaluation_point": "post-play"; readonly "basis": OrdinaryT2Basis}>;
export type Bridge = Readonly<{readonly "kind": ("started-initial" | "ordinary-only-confirmed"); readonly "v1Ref": V1Ref; readonly "ordinaryPlayCount": Unsigned; readonly "allPlayCount": Unsigned; readonly "historyDepth": Unsigned; readonly "lastSource": (PlayIdentity | null); readonly "priorArtifactSha256": Digest; readonly "rulesDigest": Digest; readonly "layoutDigest": Digest; readonly "checkpoint": Checkpoint}>;
export type Responsibility = Readonly<{readonly "kind": ("no-change" | "one-change" | "unresolved"); readonly "paStartSource": Readonly<{readonly "kind": ("started-game" | "confirmed-play"); readonly "id": Uuid}>; readonly "previousPitcherId": (Uuid | null); readonly "strikesAtChange": (Unsigned | null); readonly "ballsAtChange": (Unsigned | null)}>;
export type Source = Readonly<{readonly "kind": ("bridged-v1" | "evaluated-prefix-v2" | "locked-prefix-v2"); readonly "prefixRef": PrefixRef; readonly "rules": SavedRuleWire; readonly "after": Snapshot; readonly "t2": ((PlayT2 | OrdinaryT2 | T2NoEndCore) | null); readonly "historyDepth": Unsigned; readonly "playCount": Unsigned; readonly "lastSource": (PlayIdentity | null); readonly "position": Position; readonly "priorArtifactSha256": Digest; readonly "executionArtifactSha256": Digest; readonly "rulesDigest": Digest; readonly "layoutDigest": Digest; readonly "runners": readonly (Runner)[]; readonly "participants": Participant; readonly "nextBatter": (NextBatter | null); readonly "bridge": (Bridge | null); readonly "responsibility": Responsibility}>;
export type PlayT1Input = Readonly<{readonly "eventKind": string; readonly "resultId": string; readonly "pitchEventKind": string; readonly "before": Snapshot}>;
export type PlayRequest = Readonly<{readonly "version": "2"; readonly "prefixRef": PrefixRef; readonly "rules": SavedRuleWire; readonly "t1": PlayT1Input; readonly "source": Source; readonly "playIdentity": PlayIdentity; readonly "nextCheckpoint": Checkpoint}>;
export type PlayT1 = Readonly<{readonly "countEffect": Readonly<{readonly "strikes": (Readonly<{readonly "kind": "reset"}> | Readonly<{readonly "kind": "unchanged"}> | Readonly<{readonly "kind": "delta"; readonly "value": "1"}>); readonly "balls": (Readonly<{readonly "kind": "reset"}> | Readonly<{readonly "kind": "unchanged"}> | Readonly<{readonly "kind": "delta"; readonly "value": "1"}>)}>; readonly "plateAppearanceEnded": boolean; readonly "batterDestination": (Readonly<{readonly "kind": "continue"}> | Readonly<{readonly "kind": "reach"; readonly "base": "1"}>); readonly "runnerDefaultAdvance": Readonly<{readonly "first": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>; readonly "second": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>; readonly "third": Readonly<{readonly "modality": ("hold" | "not-applicable"); readonly "destination": null}>}>; readonly "outEffect": Readonly<{readonly "count": "0"; readonly "targets": []}>; readonly "statFlags": StatFlags; readonly "after": Snapshot}>;
export type PlayValue = Readonly<{readonly "t1": PlayT1; readonly "t2": PlayT2; readonly "newHistoryEntry": HistoryEntry; readonly "previousPrefixRef": PrefixRef; readonly "nextPrefixRef": PrefixRef; readonly "runners": readonly (Runner)[]; readonly "participants": Participant; readonly "playIdentity": PlayIdentity; readonly "sourcePosition": Position; readonly "executionArtifactSha256": Digest}>;
export type PlaySuccess = Readonly<{readonly "ok": true; readonly "value": PlayValue}>;
export type PlayFailure = Readonly<{readonly "ok": false; readonly "error": Readonly<{readonly "code": ("INVALID_JSON" | "INVALID_REQUEST" | "INVALID_DECIMAL_INTEGER" | "UNSUPPORTED_T1_SCOPE" | "T2_NOT_EVALUATED" | "PREFIX_SOURCE_MISMATCH")}>}>;
export type PlayResponse = (PlaySuccess | PlayFailure);
